head.script:
scwin.onpageload = function () {
    scwin.loadModuleList();
};

/*----------------------------모듈 동적 로딩----------------------------*/
scwin.loadModuleList = function () {
    $p.executeSubmission("sbm_moduleList");
};

scwin.sbm_moduleList_submitdone = function (e) {
    console.log("✅ 서브미션 성공! 응답 데이터:", e);

    var moduleCount = dlt_moduleList.getTotalRow();
    console.log("로드된 모듈 수:", moduleCount);

    if (moduleCount > 0) {
        console.log("모듈 데이터 확인:");
        for (var i = 0; i < moduleCount; i++) {
            var moduleData = dlt_moduleList.getRowJSON(i);
            console.log("모듈 " + (i+1) + ":", moduleData);
        }

        // ✅ DOM 렌더링 이후 안전하게 실행
        setTimeout(function () {
            scwin.createModuleElements();
        }, 0);
    } else {
        console.log("⚠️ 모듈 데이터가 없습니다.");
    }
};


scwin.sbm_moduleList_submiterror = function (e) {
    console.log("❌ 서브미션 실패:", e);
    alert("모듈 목록을 불러오는데 실패했습니다: " + e.errorMsg);
};

scwin.createModuleElements = function () {
    console.log("모듈 요소 생성 시작...");

    var moduleCount = dlt_moduleList.getTotalRow();
    console.log("생성할 모듈 수:", moduleCount);

    // 기존 모듈 요소들 제거
    var parentGroup = document.getElementById("mf_contentFrame_fr_session_making_process_grp_module_list");
    if (parentGroup) {
        parentGroup.innerHTML = '';
        console.log(" 기존 모듈 요소들 제거 완료");
    }

    // 각 모듈에 대해 요소 생성
    for (var i = 0; i < moduleCount; i++) {
        var moduleData = dlt_moduleList.getRowJSON(i);
        console.log(" 모듈 생성 중:", moduleData);
        scwin.createSingleModule(parentGroup, moduleData, i);
    }

    console.log("✨ 모든 모듈 요소 생성 완료!");
};

scwin.createSingleModule = function (parentGroup, moduleData, index) {
    var moduleId = "grp_module_" + moduleData.moduleId;
    console.log(" 개별 모듈 생성:", moduleId, moduleData);

    var moduleGroup = document.createElement("div");
    moduleGroup.id = moduleId;
    moduleGroup.className = "w2group module-card";

    moduleGroup.addEventListener("mousedown", scwin.module_mouseDown);
    moduleGroup.addEventListener("mousemove", scwin.global_mouseMove);
    moduleGroup.addEventListener("mouseup", scwin.global_mouseUp);

    parentGroup.appendChild(moduleGroup);

    scwin.createModuleContent(moduleGroup, moduleData);
    console.log("✅ 모듈 생성 완료:", moduleId);
}

scwin.createModuleContent = function (moduleGroup, moduleData) {
    console.log(" 모듈 콘텐츠 생성:", moduleData);

    moduleGroup.innerHTML = '';

    var iconSpan = document.createElement("span");
    iconSpan.id = "span_icon_" + moduleData.moduleId;
    iconSpan.textContent = moduleData.icon || "";
    iconSpan.className = "module-icon floating";
    moduleGroup.appendChild(iconSpan);

    var nameSpan = document.createElement("span");
    nameSpan.id = "span_name_" + moduleData.moduleId;
    nameSpan.textContent = moduleData.name || "모듈명";
    nameSpan.className = "module-name";
    moduleGroup.appendChild(nameSpan);

    var descSpan = document.createElement("span");
    descSpan.id = "span_desc_" + moduleData.moduleId;
    descSpan.textContent = moduleData.description || "설명";
    descSpan.className = "module-desc";
    moduleGroup.appendChild(descSpan);

    console.log(" 모듈 콘텐츠 완료:", moduleData.name);
};

/*----------------------------드래그앤드롭----------------------------*/
scwin.isDragging = false;
scwin.draggedModuleId = null;

scwin.module_mouseDown = function (e, comp) {
    scwin.isDragging = true;
    scwin.draggedModuleId = "mf_" + this.id;

    console.log("드래그 시작:", scwin.draggedModuleId);

    if (e.preventDefault) e.preventDefault();
    if (e.stopPropagation) e.stopPropagation();

    document.body.style.userSelect = 'none';
    document.body.style.webkitUserSelect = 'none';
    document.body.style.mozUserSelect = 'none';
    document.body.style.msUserSelect = 'none';

    document.body.style.cursor = 'grabbing';

    document.addEventListener('mousemove', scwin.global_mouseMove);
    document.addEventListener('mouseup', scwin.global_mouseUp);

    return false;
};

scwin.global_mouseMove = function (e) {
    if (!scwin.isDragging) return;

    console.log("전체 드래그 중.. -> 위치:", e.clientX, e.clientY);
};

scwin.global_mouseUp = function (e) {
    if (!scwin.isDragging) return;

    console.log("전체 드래그 종료:", e.clientX, e.clientY);

    scwin.checkDropZone(e.clientX, e.clientY);

    scwin.isDragging = false;
    scwin.draggedModuleId = null;

    document.body.style.userSelect = '';
    document.body.style.mozUserSelect = '';
    document.body.style.msUserSelect = '';

    document.body.style.cursor = 'default';

    document.removeEventListener('mousemove', scwin.global_mouseMove);
    document.removeEventListener('mouseup', scwin.global_mouseUp);
};

/*----------------------------모듈 배치----------------------------*/

scwin.displayModuleInArea = function (zoneId, moduleId) {
    var areaComponent = $p.getComponentById(zoneId);
    if (!areaComponent) {
        console.log("영역을 찾을 수 없습니다: ", zoneId);
        return;
    }

    var moduleInfo = scwin.getModuleData(moduleId);
    console.log("배치하는 모듈 정보:", moduleInfo);

    var areaElement = document.getElementById(zoneId);
    if (areaElement) {
        areaElement.classList.add('occupied');

        var labelElement = areaElement.querySelector('span');
        if (labelElement) {
            labelElement.innerHTML = moduleInfo.icon + " " + moduleInfo.name;
            labelElement.style.color = "white";
            labelElement.style.fontWeight = "600";
            labelElement.style.textShadow = "0 2px 8px rgba(0,0,0,0.5)";
        }

        areaElement.dataset.moduleId = moduleId.replace("mf_grp_module_", "");
        areaElement.dataset.hasModule = "true";

        console.log(zoneId, "에 모듈 ", areaElement.dataset.moduleId, " 저장");
    }
};

scwin.getModuleData = function (moduleId) {
    console.log(" 모듈 데이터 검색:", moduleId);

    var realModuleId = moduleId.replace("mf_grp_module_", "");
    console.log(" 실제 모듈 ID:", realModuleId);

    var moduleCount = dlt_moduleList.getTotalRow();

    for (var i = 0; i < moduleCount; i++) {
        var moduleData = dlt_moduleList.getRowJSON(i);
        if (moduleData.moduleId === realModuleId) {
            console.log("✅ 모듈 데이터 발견:", moduleData);
            return {
                icon: moduleData.icon || "",
                name: moduleData.name || "모듈명",
                desc: moduleData.description || "설명"
            };
        }
    }

    console.log("⚠️ 모듈 데이터를 찾을 수 없음:", realModuleId);
    return { icon: "❓", name: "알 수 없음", desc: "모듈 정보 없음" };
};

scwin.handleDrop = function (zoneId) {
    scwin.displayModuleInArea(zoneId, scwin.draggedModuleId);
};

scwin.checkDropZone = function (x, y) {
    console.log("드롭 위치 체크:", x, y, "모듈:", scwin.draggedModuleId);

    var elementAtPosition = document.elementFromPoint(x, y);

    if (!elementAtPosition) {
        console.log("드롭 실패: 요소를 찾을 수 없음");
        return;
    }

    var dropZoneElement = scwin.findDropZoneElement(elementAtPosition);

    if (dropZoneElement) {
        var zoneId = dropZoneElement.id;
        console.log("드롭 성공! 영역:", zoneId);

        scwin.handleDrop(zoneId);
    } else {
        console.log("드롭 실패: 유효한 영역이 아님");
    }
};

scwin.findDropZoneElement = function (element) {
    var validDropZones = ["mf_contentFrame_fr_session_making_process_grp_area1", "mf_contentFrame_fr_session_making_process_grp_area2", "mf_contentFrame_fr_session_making_process_grp_area3", "mf_contentFrame_fr_session_making_process_grp_area4", "mf_contentFrame_fr_session_making_process_grp_area5", "mf_contentFrame_fr_session_making_process_grp_area6","mf_contentFrame_fr_session_making_process_grp_area7", "mf_contentFrame_fr_session_making_process_grp_area8", "mf_contentFrame_fr_session_making_process_grp_area9", "mf_contentFrame_fr_session_making_process_grp_area10", "mf_contentFrame_fr_session_making_process_grp_area11", "mf_contentFrame_fr_session_making_process_grp_area12", "mf_contentFrame_fr_session_making_process_grp_area13", "mf_contentFrame_fr_session_making_process_grp_area14", "mf_contentFrame_fr_session_making_process_grp_area15", "mf_contentFrame_fr_session_making_process_grp_area16", "mf_contentFrame_fr_session_making_process_grp_area17"];

    var currentElement = element;
    var stepCount = 0;

    while (currentElement && currentElement !== document.body && stepCount < 10) {
        stepCount++;

        for (var i = 0; i < validDropZones.length; i++) {
            if (currentElement.id === validDropZones[i]) {
                console.log("유효 드롭 영역 발견:", currentElement.id);
                return currentElement;
            }
        }

        currentElement = currentElement.parentElement;
    }

    console.log("=== 드롭 영역 찾기 실패 ===");
    return null;
};

/*----------------------------모듈 배치 정보 저장----------------------------*/

scwin.saveLayoutConfiguration = function() {
    console.log("저장 버튼 클릭됨");

    var layoutDataArray = [];

    for (var i = 1; i <=17; i++) {
        var areaId = "mf_contentFrame_fr_session_making_process_grp_area" + i;
        var areaElement = document.getElementById(areaId);

        if (areaElement && areaElement.dataset.moduleId) {
            layoutDataArray.push({
                moduleId: parseInt(areaElement.dataset.moduleId),
                sessionModuleConfig: JSON.stringify({
                    area: areaId,
                    position: i
                })
            });
        }
    }

    if (layoutDataArray.length === 0) {
        alert("최소 1개 이상의 모듈을 배치해주세요.");
        return;
    }

    console.log(" 수집된 레이아웃 데이터:", layoutDataArray);

    $p.parent().scwin.setLayoutConfig(layoutDataArray);

    $p.parent().scwin.setScreen(3);
};

scwin.sbm_saveLayout_submitdone = function (e) {
    console.log("✅ 저장 서브미션 성공:", e);

    var layoutData = dlt_layoutData.getAllJSON();
    $p.parent().scwin.setLayoutConfig(layoutData);

    $p.parent().scwin.setScreen(3);
};

scwin.sbm_saveLayout_submiterror = function (e) {
    console.log("❌ 저장 서브미션 실패:", e);
    alert("저장 실패: " + (e.errorMsg || "오류 발생..."));
};

/*----------------------------모듈 배치 정보 로드 -> 팝업 ----------------------------*/

scwin.loadLayoutConfiguration = function (e) {
    console.log(" 팝업 호출 시작");

    var options = {
        id: "template_popup",
        type: "wframePopup",
        width: "1200px",
        height: "700px",
        top: "100px",
        left: "200px",
        popupName: "레이아웃 불러오기",
        modal: true,
        closeAction: "scwin.popup_closeAction"
    };

    console.log(" 팝업 옵션:", options);

    $p.openPopup("/InsWebApp/ui/sessionTemplate/SessionTemplate.xml", options);

    console.log("✅ 팝업 호출 완료");
};

scwin.popup_closeAction = function (argRuntimeID, argJsnInfo) {
    console.log(" 팝업 닫기 콜백 호출됨");
    console.log(" argRuntimeID:", argRuntimeID);
    console.log(" argJsnInfo:", argJsnInfo);

    var returnData = argJsnInfo.returnValue;
    console.log(" returnData:", returnData);

    if (returnData) {
        console.log(" 팝업에서 넘겨받은 레이아웃 데이터:", returnData);
    } else {
        console.log("⚠️ returnData가 없음");
    }

    return true;
};

scwin.applyTemplateLayout = function (templateData) {
    console.log(" 템플릿 데이터 적용");
    console.log(" 받은 데이터:", templateData);
};
